// Guards: live NL text must still equal the text read (P.old); last editor not a linguist. Writes as unverified.
// MODE: 'check' | 'test' (1 translation) | 'all'.
const MODE = 'all';
const cfg = $('Config').first().json;
const LING = 'qrcodelocalization@gmail.com,sabrathan@gmail.com,farahputri@gmail.com,dmluciahorea@gmail.com,roxanamoldovan25@gmail.com,mteres@terestraducciones.com,arandatrad@gmail.com,sara.guinot.trad@gmail.com,daniel@dgmultilingualservices.com,root-translations@outlook.com,austra.muizniece@gmail.com,harald.roald@gmail.com,47natcha@gmail.com,ellen.de.venter@outlook.com,ilaria.roncaglia@gmail.com,silke.luehrmann@gmx.de,boh.vozniuk@gmail.com,vidiasc@gmail.com,ivanaturcin@ymail.com,julius.valkiunas@gmail.com,jaromirvicari@me.com,karahansisman@gmail.com,katri.varvikko@gmail.com,kenneth@phraseit.dk,translation@cornell.hu,ruckova.lucia@gmail.com,marit.teichmann@gmail.com,michal.tosza@translators.org.pl,mteixeira@sacradomus.com,bruno@bsttranslations.com,nerissaneptuno@gmail.com,straus.translations@gmail.com,quentinnguyen.localize@gmail.com,therese.svardsten@gmail.com,mjlocalize@gmail.com,silis.martins@gmail.com'.split(',');
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 300)); }
const items = []; const skip = [];
for (const k of b.keys) {
  const spec = cfg.P[String(k.key_id)]; if (!spec) { continue; }
  if (k.is_archived || k.is_plural) { skip.push([k.key_id, 'archived/plural']); continue; }
  const t = (k.translations || []).find(function (x) { return x.language_iso === 'nl'; });
  const live = t ? t.translation : '';
  const by = t ? String(t.modified_by_email || '').toLowerCase() : '';
  if (live === spec.new) { skip.push([k.key_id, 'already']); continue; }
  if (live !== spec.old) { skip.push([k.key_id, 'changed since read']); continue; }
  if (LING.indexOf(by) !== -1) { skip.push([k.key_id, 'linguist edit: ' + by]); continue; }
  items.push({ key_id: k.key_id, translations: [{ language_iso: 'nl', translation: spec.new, is_unverified: true }] });
}
let sel = items;
if (MODE === 'test') { sel = items.filter(function (x) { return String(x.key_id) === '968559222'; }); }
if (MODE === 'check') { sel = []; }
const reqs = [];
for (let i = 0; i < sel.length; i += 10) { reqs.push({ body: JSON.stringify({ keys: sel.slice(i, i + 10) }) }); }
return [{ json: { mode: MODE, expected: Object.keys(cfg.P).length, found: b.keys.length, ready: items.length, to_write: sel.length, skipped: skip.length, skip_list: skip, requests: reqs } }];

const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { return [{ json: { error: 'read-back failed', body: JSON.stringify(b).slice(0, 300) } }]; }
let match = 0; const diff = [];
for (const k of b.keys) {
  const spec = cfg.P[String(k.key_id)]; if (!spec) { continue; }
  const t = (k.translations || []).find(function (x) { return x.language_iso === 'nl'; });
  if (t && t.translation === spec.new) { match++; } else { diff.push([k.key_id, t ? t.translation : null]); }
}
let res = [];
try { res = $('WRITE translations').all().map(function (x) { return { status: x.json.statusCode, written: ((x.json.body || {}).keys || []).length, errors: (x.json.body || {}).errors || null }; }); } catch (e) { res = ['no write this run']; }
return [{ json: { write_results: res, readback: { match: match, different: diff.length, diff: diff } } }];
